<#
.SYNOPSIS
    libbroadvoice: builds libbroadvoice.dll (the BV16 / BV32 codecs mod_bv uses)
    with the Visual C++ toolchain and packages it for FreeSWITCH's w32\broadvoice.props.

    FreeSWITCH used to build this in tree: w32\download_broadvoice.props fetched
    broadvoice-<version>.tar.gz from files.freeswitch.org and
    libs\win32\broadvoice\libbroadvoice.2017.vcxproj compiled it. This node does the
    same compilation, from the GitHub release of freeswitch/libbroadvoice, and ships
    the result as a package instead. The source list comes from upstream's own
    Makefile.am (libbroadvoice_la_SOURCES) plus msvc\gettimeofday.c, which its
    WIN32SOURCES adds for this platform.

    BROADVOICE_EXPORTS marks the API __declspec(dllexport) while building, so a
    consumer that does not define it links through libbroadvoice.lib, exactly as
    mod_bv does today.

    Package <pkg> = broadvoice-<version>_<build>:
      <pkg>-headers.zip                       <pkg>/COPYING
                                              <pkg>/include/broadvoice/{broadvoice.h, version.h}
                                              <pkg>/include/broadvoice/private/broadvoice.h
      <pkg>-binaries-<platform>-<config>.zip  <pkg>/COPYING
                                              <pkg>/binaries/<Platform>/<Config>/{libbroadvoice.dll, libbroadvoice.lib}
                                                                             /libbroadvoice.pdb   (Debug only)
      SHA256SUMS.txt, <pkg>-BOM.txt

    mod_bv includes "broadvoice.h", which is include\broadvoice\broadvoice.h: the
    property sheet puts both include\ and include\broadvoice\ on the include path,
    the way the in tree build did. The top level broadvoice.h of the autotools
    build is generated by configure and never existed on Windows.

    Environment (all optional): BROADVOICE_VERSION, BUILD_NUMBER, PKG_NAME, CONFIGS,
    PLATFORMS, OUT_DIR, BUILD_ROOT, BROADVOICE_URL, EXTRA_CFLAGS.
#>
[CmdletBinding()]
param()

. (Join-Path $PSScriptRoot '..\..\scripts\common.ps1')

$s  = Get-BuildSettings 'broadvoice'
$tc = Initialize-Toolchain
$extraCFlags = [string](Get-EnvValue 'EXTRA_CFLAGS' '')

foreach ($c in $s.Configs) {
    if ($c -notin @('Release', 'Debug')) { throw "Unsupported configuration '$c' (use 'Release' and/or 'Debug')." }
}

Write-Host "==================================================================="
Write-Host " broadvoice      : $($s.Version) (build $($s.Build), package $($s.Pkg))"
Write-Host " Source URL      : $($s.SourceUrl)"
Write-Host " Platforms       : $($s.Platforms -join ', ')"
Write-Host " Configs         : $($s.Configs -join ', ')"
Write-Host " Extra cflags    : $extraCFlags"
Write-Host " VS install      : $($tc.VsInstall)"
Write-Host " Build root      : $($s.BuildRoot)"
Write-Host " Output dir      : $($s.OutDir)"
Write-Host "==================================================================="

Reset-Directory $s.BuildRoot
New-Item -ItemType Directory -Force -Path $s.OutDir | Out-Null
$stage = Join-Path $s.BuildRoot 'stage'
New-Item -ItemType Directory -Force -Path $stage | Out-Null

$tarball = Join-Path $s.BuildRoot "libbroadvoice-$($s.Version).tar.gz"
Get-RemoteFile $s.SourceUrl $tarball

$headerSrc = $null

foreach ($plat in $s.Platforms) {
    $vcArch = Get-VcArch $plat
    foreach ($config in $s.Configs) {
        Write-Host "-------------------------------------------------------------------"
        Write-Host "Building libbroadvoice $($s.Version)  [$plat / $config]  (cl + link, DLL)"
        Write-Host "-------------------------------------------------------------------"

        $work = Join-Path $s.BuildRoot "build-$plat-$config"
        New-Item -ItemType Directory -Force -Path $work | Out-Null
        Expand-Tarball $tarball $work $tc
        $root = Join-Path $work "libbroadvoice-$($s.Version)"
        if (-not (Test-Path $root)) { throw "Tarball did not expand to '$root'." }
        $src = Join-Path $root 'src'

        # The version upstream's configure.ac declares must match the manifest.
        $ac = Get-Content (Join-Path $root 'configure.ac') -Raw -ErrorAction SilentlyContinue
        if ($ac -and $ac -match 'AC_INIT\(\[?libbroadvoice\]?,\s*\[?([0-9][0-9.]*)\]?') {
            if ($Matches[1] -ne $s.Version) { throw "libbroadvoice source declares version $($Matches[1]) but deps.json says $($s.Version)." }
        } else {
            Write-Host "WARNING: could not read the version from configure.ac, not cross-checked."
        }

        # Source list straight out of upstream's Makefile.am, plus the one file its
        # WIN32SOURCES adds for this platform.
        $mk = (Get-Content (Join-Path $src 'Makefile.am') -Raw) -replace '\\\r?\n', ' '
        if ($mk -notmatch '(?m)^libbroadvoice_la_SOURCES\s*=\s*([^\r\n]*)$') { throw "No libbroadvoice_la_SOURCES in src\Makefile.am." }
        $names = @($Matches[1] -split '\s+' | Where-Object { $_ -like '*.c' })
        $names += 'msvc\gettimeofday.c'
        if ($names.Count -lt 40) { throw "Only $($names.Count) sources listed in Makefile.am -- the tree layout changed." }
        $sources = foreach ($n in $names) {
            $p = Join-Path $src ($n -replace '/', '\')
            if (-not (Test-Path $p)) { throw "'$n' is listed in Makefile.am but missing." }
            $p
        }
        $dupes = $sources | Group-Object { [System.IO.Path]::GetFileName($_) } | Where-Object { $_.Count -gt 1 }
        if ($dupes) { throw "Duplicate source file names: $(($dupes | ForEach-Object { $_.Name }) -join ', ')." }
        Write-Host ("sources: {0} files" -f $sources.Count)

        $objDir = Join-Path $work 'obj'
        $binDir = Join-Path $work 'bin'
        New-Item -ItemType Directory -Force -Path $objDir, $binDir | Out-Null

        # The same knobs the in tree vcxproj used.
        $crt = if ($config -eq 'Debug') { '/MDd' } else { '/MD' }
        $opt = if ($config -eq 'Debug') { '/Od /Zi /D_DEBUG' } else { '/O2 /DNDEBUG' }
        $inc = @('.', 'floating\common', 'floating\bv16', 'floating\bv32', 'broadvoice', 'msvc') |
               ForEach-Object { "/I`"$(Join-Path $src $_)`"" }
        $clRsp = @("/nologo /c $crt $opt /W3 /DWIN32 /D_WINDOWS /D_USRDLL /DBROADVOICE_EXPORTS /D_CRT_SECURE_NO_DEPRECATE /D_CRT_NONSTDC_NO_DEPRECATE /DHAVE_TGMATH_H $extraCFlags",
                   ($inc -join ' '), "/Fo`"$objDir\\`"", "/Fd`"$objDir\compiler.pdb`"") +
                 ($sources | ForEach-Object { "`"$_`"" })
        Set-Content -Path (Join-Path $work 'cl.rsp') -Value $clRsp -Encoding ASCII

        $dll = Join-Path $binDir 'libbroadvoice.dll'
        $lib = Join-Path $binDir 'libbroadvoice.lib'
        $pdb = Join-Path $binDir 'libbroadvoice.pdb'
        $objects = $sources | ForEach-Object { Join-Path $objDir ([System.IO.Path]::GetFileNameWithoutExtension($_) + '.obj') }
        $linkRsp = @('/nologo /DLL', "/OUT:`"$dll`"", "/IMPLIB:`"$lib`"") +
                   $(if ($config -eq 'Debug') { @('/DEBUG', "/PDB:`"$pdb`"") } else { @() }) +
                   ($objects | ForEach-Object { "`"$_`"" })
        Set-Content -Path (Join-Path $work 'link.rsp') -Value $linkRsp -Encoding ASCII

        $bat = @"
@echo on
call "$($tc.VcVarsAll)" $vcArch || exit /b 1
cl @"$(Join-Path $work 'cl.rsp')" || exit /b 1
link @"$(Join-Path $work 'link.rsp')" || exit /b 1
dumpbin /nologo /exports "$dll" > "$(Join-Path $work 'exports.txt')" || exit /b 1
"@
        $log = Join-Path $s.OutDir "build-$plat-$config.log"
        Invoke-BuildBatch -Script $bat -BatchFile (Join-Path $work 'build.bat') -LogFile $log -Label "broadvoice build [$plat/$config]"

        # --- verify --------------------------------------------------------------
        foreach ($f in $dll, $lib) { if (-not (Test-Path $f)) { throw "broadvoice [$plat/$config] did not produce $(Split-Path -Leaf $f)." } }
        $exports = Get-Content (Join-Path $work 'exports.txt') -Raw
        foreach ($sym in 'bv16_encode_init', 'bv16_encode', 'bv16_decode', 'bv16_fillin',
                         'bv32_encode_init', 'bv32_encode', 'bv32_decode', 'bv32_fillin') {
            if ($exports -notmatch "\b$sym\b") { throw "libbroadvoice.dll does not export $sym -- BROADVOICE_EXPORTS did not take effect." }
        }

        # --- stage ---------------------------------------------------------------
        $pkgRoot = Join-Path $stage "bin-$plat-$config\$($s.Pkg)"
        $binDst  = Join-Path $pkgRoot "binaries\$plat\$config"
        New-Item -ItemType Directory -Force -Path $binDst | Out-Null
        Copy-Item $dll, $lib -Destination $binDst
        if ($config -eq 'Debug' -and (Test-Path $pdb)) { Copy-Item $pdb -Destination $binDst }
        Copy-Item (Join-Path $root 'COPYING') -Destination $pkgRoot -ErrorAction SilentlyContinue
        New-PackageZip $pkgRoot (Join-Path $s.OutDir ("$($s.Pkg)-binaries-$plat-$config.zip".ToLower()))

        if (-not $headerSrc) { $headerSrc = $root }
    }
}

# --- headers zip -------------------------------------------------------------------
# Upstream's nobase_include_HEADERS: the three public headers, keeping their
# broadvoice\ prefix so #include "broadvoice.h" and <broadvoice/broadvoice.h> both work.
Write-Host "-------------------------------------------------------------------"
Write-Host "Packaging headers ..."
$hdrRoot = Join-Path $stage "hdr\$($s.Pkg)"
$incDst  = Join-Path $hdrRoot 'include\broadvoice'
New-Item -ItemType Directory -Force -Path (Join-Path $incDst 'private') | Out-Null
foreach ($h in 'broadvoice.h', 'version.h') {
    Copy-Item (Join-Path $headerSrc "src\broadvoice\$h") -Destination $incDst
}
Copy-Item (Join-Path $headerSrc 'src\broadvoice\private\broadvoice.h') -Destination (Join-Path $incDst 'private')
Copy-Item (Join-Path $headerSrc 'COPYING') -Destination $hdrRoot -ErrorAction SilentlyContinue
foreach ($must in 'broadvoice\broadvoice.h', 'broadvoice\version.h', 'broadvoice\private\broadvoice.h') {
    if (-not (Test-Path (Join-Path $hdrRoot "include\$must"))) { throw "Headers package is missing include\$must." }
}
New-PackageZip $hdrRoot (Join-Path $s.OutDir ("$($s.Pkg)-headers.zip".ToLower()))

Write-Checksums $s.OutDir
Write-Bom $s @("toolchain: $($tc.VsInstall)", "library: libbroadvoice.dll + libbroadvoice.lib",
               "features: BV16 + BV32 floating point, BROADVOICE_EXPORTS, /MD")
Write-PackageSummary $s
